 \begin{aligned} & \frac{\sqrt{3}}{2} \mu=\frac{1}{4} \\\\ & \mu=\frac{1}{2 \sqrt{3}} \end{aligned}

\begin{aligned} \mathrm{f}_{\mathrm{K}} & =\mu \mathrm{mg} \cos \theta \\ & =0.1 \times \frac{50 \times \sqrt{3}}{2} \\ & =2.5 \sqrt{3} \mathrm{~N} \end{aligned} 

